1	# TikTok orders multi-store scrape (P2a) via ziniao-cli
2	# Usage:
3	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-orders.ps1
4	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-orders.ps1 -ListOnly
5	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-orders.ps1 -DryRun true
6	#
7	# Requires: Ziniao client + Bridge; config\stores.config.json
8	# Does NOT write Feishu by default (orders Feishu table optional later) — only Qingquan ingest.
9	
10	param(
11	  [string]$ConfigPath = "",
12	  [switch]$ListOnly,
13	  [string]$DryRun = ""
14	)
15	
16	$ErrorActionPreference = 'Stop'
17	$PSNativeCommandUseErrorActionPreference = $false
18	$root = Split-Path $PSScriptRoot -Parent
19	if (-not $ConfigPath) { $ConfigPath = Join-Path $root 'config\stores.config.json' }
20	$scrapeJsPath = Join-Path $root 'scripts\scrape-orders-page.js'
21	$clickNextJsPath = Join-Path $root 'scripts\orders-click-next.js'
22	$detailJsPath = Join-Path $root 'scripts\scrape-order-detail-page.js'
23	if (-not (Test-Path $ConfigPath)) { throw "Missing config: $ConfigPath" }
24	if (-not (Test-Path $scrapeJsPath)) { throw "Missing $scrapeJsPath" }
25	
26	$cfg = Get-Content $ConfigPath -Raw -Encoding UTF8 | ConvertFrom-Json
27	$scrapeJs = Get-Content $scrapeJsPath -Raw -Encoding UTF8
28	$clickNextJs = ''
29	if (Test-Path $clickNextJsPath) {
30	  $clickNextJs = Get-Content $clickNextJsPath -Raw -Encoding UTF8
31	}
32	$detailJs = ''
33	if (Test-Path $detailJsPath) {
34	  $detailJs = Get-Content $detailJsPath -Raw -Encoding UTF8
35	}
36	$qingquanLib = Join-Path $PSScriptRoot 'qingquan-client.ps1'
37	if (Test-Path $qingquanLib) { . $qingquanLib }
38	$ziniaoWinLib = Join-Path $PSScriptRoot 'ziniao-window.ps1'
39	if (-not (Test-Path $ziniaoWinLib)) { throw "Missing $ziniaoWinLib" }
40	. $ziniaoWinLib
41	
42	$script:logsDir = Join-Path $root 'logs'
43	New-Item -ItemType Directory -Force -Path $script:logsDir | Out-Null
44	$script:runStamp = Get-Date -Format 'yyyyMMdd-HHmmss'
45	$script:runLogFile = Join-Path $script:logsDir ("orders-run-{0}.log" -f $script:runStamp)
46	
47	function Write-RunLog([string]$msg) {
48	  $line = "[{0}] {1}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $msg
49	  try { Add-Content -LiteralPath $script:runLogFile -Value $line -Encoding UTF8 } catch { }
50	}
51	function Write-Step([string]$msg) {
52	  Write-Host ("[{0}] {1}" -f (Get-Date -Format 'HH:mm:ss'), $msg)
53	  Write-RunLog $msg
54	}
55	
56	function ConvertTo-ProcessArgument([string]$s) {
57	  if ($null -eq $s) { return '""' }
58	  if ($s -match '[\s"]') { return '"' + ($s -replace '"', '\"') + '"' }
59	  return $s
60	}
61	
